using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Globalization;using System.Collections.Generic;using VisionDesigner;using VisionDesigner.ImageBinary;
class SectorProbe {
 [DllImport("kernel32",CharSet=CharSet.Unicode)] static extern bool SetDllDirectory(string path);
 static int Main(string[] args){SetDllDirectory(Path.Combine(args[0],"Runtime","x64"));var output=args[1];Directory.CreateDirectory(output);try{foreach(int size in new[]{16,64}){string input=Path.Combine(output,"input"+size+".bmp");using(var b=new Bitmap(size,size)){for(int y=0;y<size;y++)for(int x=0;x<size;x++)b.SetPixel(x,y,Color.White);b.Save(input,ImageFormat.Bmp);}using(var image=new CMvdImage()){image.InitImage(input,MVD_PIXEL_FORMAT.MVD_PIXEL_MONO_08);int id=0;using(var csv=new StreamWriter(Path.Combine(output,"cases"+size+".csv"))){csv.WriteLine("file,cx,cy,inner,outer,start,sweep");foreach(float outer in size==16?new float[]{6,5.5f}:new float[]{15,14.5f})foreach(float inner in new float[]{0,3})foreach(float start in new float[]{0,30,-90})foreach(float sweep in new float[]{45,90,180,270,360}){string name="s"+size+"-"+(id++)+".bmp";var p=new MVD_POINT_F();p.fX=size/2;p.fY=size/2;using(var tool=new CImageBinaryTool()){tool.InputImage=image;tool.SetRunParam("BinaryType","1");tool.SetRunParam("LowThreshold","0");tool.SetRunParam("HighThreshold","255");tool.ROI=new CMvdAnnularSectorF(p,inner,outer,start,sweep);tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,name));}csv.WriteLine(string.Join(",",new[]{name,p.fX.ToString(CultureInfo.InvariantCulture),p.fY.ToString(CultureInfo.InvariantCulture),inner.ToString(CultureInfo.InvariantCulture),outer.ToString(CultureInfo.InvariantCulture),start.ToString(CultureInfo.InvariantCulture),sweep.ToString(CultureInfo.InvariantCulture)}));}}}}return 0;}catch(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());return 1;}}
}
